'use strict'

const NavigationCatalog = require('./navigation-catalog')

const $unsafe = Symbol.for('unsafe')

const LINK_RX = /^<a href="([^"]+)"( [^>]+)?>(.+?)<\/a>$/
const SPAN_RX = /^<span class="([^"]+)">(.+?)<\/span>$/
const ATTR_RX = / +([a-z]+)="([^"]+)"/g
const XREF_RX = /<a href="[^"]+" class="xref [^>]*>(.+?)<\/a>/g
const REQUISITE_ASCIIDOC_CONFIG = { doctype: 'article', extensions: [], relativizeResourceRefs: false }

/**
 * Builds a {NavigationCatalog} from files in the navigation family that are stored in the content catalog.
 *
 * Queries the content catalog for files in the navigation family. Then uses the AsciiDoc Loader component to parse the
 * source of each file into an Asciidoctor Document object. It then looks in each file for one or more nested unordered
 * lists, which are used to build the navigation trees. It then combines those trees in sorted order as a navigation
 * set, which gets stored in the navigation catalog by component/version pair as well as on the component version.
 *
 * @memberof navigation-builder
 *
 * @param {ContentCatalog} contentCatalog - The content catalog that provides access to the virtual files for the site.
 * @param {Object} [defaultAsciiDocConfig=undefined] - AsciiDoc processor configuration if not provided by the component
 *   version. Typically the value of the siteAsciiDocConfig context variable. The relativizeResourceRefs option is set
 *   to false before passing to loadAsciiDoc function. Extensions are not propagated.
 * @returns {NavigationCatalog} A navigation catalog built from the navigation files in the content catalog.
 */
function buildNavigation (contentCatalog, defaultAsciiDocConfig) {
  const { loadAsciiDoc = require('@antora/asciidoc-loader') } = this ? this.getFunctions($unsafe) : {}
  const navCatalog = new NavigationCatalog()
  const navFilesByComponentVersion = new Map()
  contentCatalog.findBy({ family: 'nav' }).forEach((navFile) => {
    const { component, version } = navFile.src
    const key = version + '@' + component
    if (navFilesByComponentVersion.has(key)) {
      navFilesByComponentVersion.get(key).navFiles.push(navFile)
      return
    }
    const componentVersion = contentCatalog.getComponentVersion(component, version)
    const componentVersionAsciiDocConfig = componentVersion.asciidoc ?? defaultAsciiDocConfig
    const asciidocConfig = Object.assign({}, componentVersionAsciiDocConfig, REQUISITE_ASCIIDOC_CONFIG)
    navFilesByComponentVersion.set(key, { component, version, componentVersion, asciidocConfig, navFiles: [navFile] })
  })
  navFilesByComponentVersion.forEach(({ component, version, componentVersion, asciidocConfig, navFiles }) => {
    const navigation = navFiles.reduce((accum, navFile) => {
      accum.push(...loadNavigationFile(loadAsciiDoc, navFile, contentCatalog, asciidocConfig, navFile.nav.index))
      return accum
    }, [])
    componentVersion.navigation = navCatalog.addNavigation(component, version, navigation)
  })
  return navCatalog
}

function buildAlternateNavigation (contentCatalog, componentVersion, navFiles, asciidocConfigOverrides) {
  const { loadAsciiDoc = require('@antora/asciidoc-loader') } = this ? this.getFunctions($unsafe) : {}
  let honorNavIndex
  navFiles ??=
    (honorNavIndex = true) &&
    contentCatalog.findBy({ component: componentVersion.name, version: componentVersion.version, family: 'nav' })
  const navAsciiDocConfig = Object.assign({}, componentVersion.asciidoc)
  if (asciidocConfigOverrides) {
    const attributesOverrides =
      'attributes' in asciidocConfigOverrides
        ? { attributes: Object.assign({}, navAsciiDocConfig.attributes, asciidocConfigOverrides.attributes) }
        : undefined
    Object.assign(navAsciiDocConfig, asciidocConfigOverrides, attributesOverrides)
  }
  Object.assign(navAsciiDocConfig, REQUISITE_ASCIIDOC_CONFIG)
  const navigation = navFiles.reduce((accum, navFile, idx) => {
    const index = honorNavIndex ? navFile.nav.index : idx
    accum.push(...loadNavigationFile(loadAsciiDoc, navFile, contentCatalog, navAsciiDocConfig, index))
    return accum
  }, [])
  if (honorNavIndex) navigation.sort((a, b) => a.order - b.order)
  return navigation
}

function loadNavigationFile (loadAsciiDoc, navFile, contentCatalog, asciidocConfig, navIndex) {
  const lists = loadAsciiDoc(navFile, contentCatalog, asciidocConfig).blocks.filter((b) => b.getContext() === 'ulist')
  if (!lists.length) return []
  return lists.map((list, idx) => {
    const tree = buildNavigationTree(list, true)
    tree.root = true
    tree.order = idx ? parseFloat((navIndex + idx / lists.length).toFixed(4)) : navIndex
    return tree
  })
}

function getChildListItems (listItem) {
  const blocks = listItem.getBlocks()
  const candidate = blocks[0]
  if (candidate) {
    if (blocks.length === 1 && candidate.getContext() === 'ulist') return candidate.getItems()
    let context
    return blocks.reduce((accum, block) => {
      if (
        (context = block.getContext()) === 'ulist' ||
        (context === 'open' && (block = block.getBlocks()[0]) && block.getContext() === 'ulist')
      ) {
        accum.push(...block.getItems())
      }
      return accum
    }, [])
  }
  return []
}

function buildNavigationTree (listItem, isRoot) {
  const entry = modelContent(listItem, isRoot)
  const childListItems = isRoot ? listItem.getItems() : entry.content ? getChildListItems(listItem) : []
  if (!childListItems.length) return entry
  const items = childListItems.map((item) => buildNavigationTree(item)).filter(({ content }) => content)
  if (items.length) entry.items = items
  return entry
}

function modelContent (contentNode, isRoot) {
  const content = isRoot ? contentNode.getTitle() : contentNode.getText()
  if (!content) return {}
  const model = { content }
  let match
  if (~content.indexOf('<a ')) {
    if (content.startsWith('<a ') && (match = content.match(LINK_RX)) && !~match[3].indexOf('<a ')) {
      const [, url, attrString, linkText] = match
      model.content = linkText
      model.url = url
      const linkProps = {}
      const roles = {}
      if (attrString) {
        const attrScanner = new RegExp(ATTR_RX)
        let attrMatch
        while ((attrMatch = attrScanner.exec(attrString))) {
          const [, name, val] = attrMatch
          switch (name) {
            case 'class':
              val
                .trim()
                .split(/ +/)
                .forEach((r) => (roles[r] = true))
              break
            case 'rel':
            case 'target':
              linkProps['link' + name.charAt().toUpperCase() + name.substring(1)] = val
              break
            case 'title':
              linkProps.advisoryInfo = val
              break
          }
        }
      }
      if (roles.xref) {
        model.urlType = 'internal'
        delete roles.xref
        if (roles.unresolved) {
          model.unresolved = true
        } else {
          const hashIdx = url.indexOf('#')
          if (~hashIdx) {
            model.pathname = url.substring(0, hashIdx)
            model.hash = url.substring(hashIdx)
          }
        }
      } else if (url.charAt() === '#') {
        model.urlType = 'fragment'
        model.hash = url
      } else {
        model.urlType = 'external'
      }
      if (!(model.roles = Object.keys(roles)).length) delete model.roles
      Object.assign(model, linkProps)
    } else {
      model.content = model.content.replace(XREF_RX, '$1')
    }
  } else if (content.startsWith('<span ') && (match = content.match(SPAN_RX))) {
    const [, className, text] = match
    model.content = text
    const roles = new Set()
    className
      .trim()
      .split(/ +/)
      .forEach((r) => roles.add(r))
    model.roles = [...roles]
  }
  return model
}

module.exports = Object.assign(buildNavigation, { buildNavigation, buildAlternateNavigation })
